import React, { useState, useEffect } from 'react';
import Head from './partials/head';
import Navbar from './partials/navbar';
import Footer from './partials/footer';
import { Modal, Button, Carousel } from 'react-bootstrap';
import { useParams } from 'react-router-dom';
import 'bootstrap/dist/css/bootstrap.min.css';
import axios from 'axios';
import config from '../config';

import { ToastContainer, toast } from "react-toastify"; // Importing react-toastify
import "react-toastify/dist/ReactToastify.css"; // Importing default styles


const AccountINFO = () => {
  const { id } = useParams();

  const [loading, setLoading] = useState(true);
  const [accountInfo, setAccountInfo] = useState(null);
  const [showModal, setShowModal] = useState(false);
  const [selectedImage, setSelectedImage] = useState('');
  const [activeIndex, setActiveIndex] = useState(0);

  const buySubmit = async () => {
    toast.error("đang phát triển...", {position: "top-right",autoClose: 5000,hideProgressBar: false,closeOnClick: true});
  }
  function convertToHCMTime(utcTime) {
    return new Date(utcTime).toLocaleString("vi-VN", {
      timeZone: "Asia/Ho_Chi_Minh",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
      hour12: false,
    });
  }
  const formatPrice = (num) => num.toLocaleString('vi');

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const response = await axios.post(`${config.API_URL}/viewAccountInfo`, { accId: id });
        if (response.data.type) {
          setAccountInfo(response.data.data);
        }
      } catch (error) {
        console.error('Error fetching account info:', error);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, [id]);

  const openModal = (image, index) => {
    setSelectedImage(image);
    setActiveIndex(index);
    setShowModal(true);
  };

  const closeModal = () => {
    setShowModal(false);
    setSelectedImage('');
  };

  const handleSelect = (selectedIndex) => {
    setActiveIndex(selectedIndex);
  };

  if (loading) {
    return (
      <div className="d-flex justify-content-center align-items-center" style={{ height: '300px' }}>
        <div className="spinner-border text-primary" role="status">
          <span className="visually-hidden">Loading...</span>
        </div>
      </div>
    );
  }

  if (!accountInfo) {
    return <div>No account information available.</div>;
  }

  return (
    <>
      <Head />
      <div className="hold-transition sidebar-collapse layout-top-nav">
        <div className="wrapper">
          <Navbar />
          <section className="content">
            <div className="container-fluid">
              <center>
                <img
                  src="https://raw.githubusercontent.com/demoiiiiibtca/img/refs/heads/main/2020031919242255224.png"
                  className="city__icon"
                  alt="City Icon"
                />
              </center>
              <main>
                <div>
                  <div className="container-lg">
                    <div className="card card-solid offset-lg-1 col-lg-10">
                      <div className="row">
                        {/* Image Section */}
                        <div className="col-12 col-sm-6">
                          <div className="image-gallery">
                            <Carousel
                              activeIndex={activeIndex}
                              onSelect={handleSelect}
                              nextIcon={<span className="carousel-control-next-icon" style={{ backgroundColor: 'black' }} />}
                              prevIcon={<span className="carousel-control-prev-icon" style={{ backgroundColor: 'black' }} />}
                            >
                              {accountInfo.bgimage?.map((image, index) => (
                                <Carousel.Item key={index}>
                                   {/* eslint-disable-next-line jsx-a11y/img-redundant-alt */}
                                  <img
                                    className="d-block w-100"
                                    src={image}
                                    alt={`Image ${index + 1}`}
                                    onClick={() => openModal(image, index)} // Open modal when image is clicked
                                  />
                                </Carousel.Item>
                              ))}
                            </Carousel>
                          </div>
                        </div>

                        {/* Account Info Section */}
                        <div className="col-12 col-sm-6">
                          <strong className="announce mt-2 mb-3"><i class="fas fa-dollar-sign"></i>{formatPrice(accountInfo.price)}</strong>
                          <center>
                            <big className="col text-center fw-bold" style={{ color: '#D19B72' }}>{accountInfo.content}</big>
                            <p></p>
                            {/* eslint-disable-next-line jsx-a11y/alt-text */}
                            <img class="img-responsive" style={{marginLeft: '-10px', width: '340px'}} src="https://shoptethan.com/style/images/hr_beautiful.webp" />
                          </center>
                          <table className="table mt-2" style={{ marginBottom: '11px', width: '100%' }}>
                            <tbody>
                              {/* Assuming accountInfo.details is an array of key-value pairs */}
                              {/* {accountInfo.details?.map((item, index) => (
                                <tr key={index}>
                                  <td><span className="list_flower"></span> {item.label}</td>
                                  <td>{item.value}</td>
                                </tr>
                              ))} */}
                              
                                <tr key={accountInfo.planet}>
                                  <td><span className="list_flower"></span> ID</td>
                                  <td>{accountInfo.idnew}</td>
                                </tr>
                                <tr key={accountInfo.planet}>
                                  <td><span className="list_flower"></span> Hành Tinh</td>
                                  <td>{accountInfo.planet}</td>
                                </tr>

                                <tr key={accountInfo.server}>
                                  <td><span className="list_flower"></span> Máy Chủ</td>
                                  <td>{accountInfo.server}</td>
                                </tr>

                                <tr key={convertToHCMTime(accountInfo.updatedAt)}>
                                  <td><span className="list_flower"></span> Đăng lúc</td>
                                  <td>{convertToHCMTime(accountInfo.updatedAt)}</td>
                                </tr>
                            </tbody>
                          </table>
                          <button className="btn_beautiful btn" type='button' onClick={buySubmit} name="submit"><i class="fas fa-cart-plus"></i> Mua ngay</button>
                        </div>
                       
                      </div>
                    </div>
                  </div>
                </div>
              </main>
              <Footer />
              <ToastContainer />
            </div>
          </section>
        </div>
      </div>

      {/* Modal to display selected image */}
      <Modal show={showModal} onHide={closeModal} size="lg" centered>
        <Modal.Body>
          <img
            src={selectedImage}
            alt="Selected"
            className="img-fluid"
            style={{ maxWidth: '100%', maxHeight: '80vh', objectFit: 'contain' }}
          />
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={closeModal}>Close</Button>
        </Modal.Footer>
      </Modal>
    </>
  );
};

export default AccountINFO;
