import React, { useState } from 'react';

const FormSearch = ({ onSearch, isLoading }) => {
    const [accId, setAccId] = useState('');
    const [server, setPrice] = useState('');
    const [sortPrice, setSortPrice] = useState('-1');
  
    const handleAccIdChange = (event) => {
      setAccId(event.target.value);
    };
  
    const handlePriceChange = (event) => {
      setPrice(event.target.value);
    };
  
    const handleSortPriceChange = (event) => {
      setSortPrice(event.target.value);
    };
  
    const handleSearch = () => {
      onSearch({ accId, server, sortPrice });
    };
  
    return (
      <div className="col-12 col-lg-3 search-zone">
        <section id="search-form" className="search-frm p-4 pb-5">
          <p className="text-center ms-text h5 m-2">Tìm kiếm</p>
          <p className="text-center small">Nhập thông tin muốn tìm</p>
          <div className="row">
            <div className="col-6 mt-3">
              <label className="form-label">Lọc theo máy chủ</label>
              <select className="form-control" name="server" value={server} onChange={handlePriceChange}>
                <option value="">Tất Cả Server</option>
                <option value="1Sao">1Sao</option>
                <option value="2Sao">2Sao</option>
                <option value="3Sao">3Sao</option>
              </select>
            </div>
            <div className="col-6 mt-3">
              <label className="form-label">Sắp xếp giá</label>
              <select className="form-control" name="sort_price" value={sortPrice} onChange={handleSortPriceChange}>
                <option value="-1">Giảm Dần</option>
                <option value="1">Tăng Dần</option>
              </select>
            </div>
          </div>
          <div className="col-12 mt-3">
            <label htmlFor="inpSearchHero" className="form-label">ID acc</label>
            <input
              className="form-control"
              name="acc_id"
              type="number"
              value={accId}
              onChange={handleAccIdChange}
              placeholder="Sẽ chuyển thẳng đến acc đó"
            />
          </div>
  
          <div className="col-12 mt-3 d-flex justify-content-center">
            <button
              name="search"
              value="search"
              type="button"
              className="col-8 form-control btn btn-warning text-white font-weight-bold"
              onClick={handleSearch}
              disabled={isLoading} // Vô hiệu hóa nút nếu đang tải
            >
              {isLoading ? (
                <span className="spinner-border spinner-border-sm text-light" role="status" aria-hidden="true"></span>
              ) : (
                <><i className="fab fa-searchengin ml-2"></i> Tìm kiếm</>
              )}
            </button>
          </div>
        </section>
      </div>
    );
  };

  export default FormSearch;
