import React from 'react';
import { HashRouter as Router, Routes, Route, useLocation } from 'react-router-dom';
import { AnimatePresence, motion } from 'framer-motion';
import Home from './client/home';
import Acctype from './client/account-category';
import Accinfo from './client/account-info';
import Login from './client/login';
import Register from './client/register';

const pageVariants = {
  initial: {
    opacity: 0,
    clipPath: 'inset(0 50% 0 50%)',
  },
  animate: {
    opacity: 1,
    clipPath: 'inset(0 0% 0 0%)',
    transition: {
      duration: 0.7,
      ease: 'easeInOut',
    },
  },
  exit: {
    opacity: 0,
    clipPath: 'inset(0 50% 0 50%)',
    transition: {
      duration: 0.7,
      ease: 'easeInOut',
    },
  },
};

const AppRouter = () => {
  const location = useLocation();

  return (
    <AnimatePresence mode="wait">
      <motion.div
        key={location.pathname} // Mỗi route cần một key duy nhất
        variants={pageVariants}
        initial="initial"
        animate="animate"
        exit="exit"
      >
        <Routes location={location}>
          <Route path="/" element={<Home />} />
          <Route path="/account/category/:id" element={<Acctype />} />
          <Route path="/account/info/:id" element={<Accinfo />} />
          <Route path="/login" element={<Login />} />
          <Route path="/register" element={<Register />} />
        </Routes>
      </motion.div>
    </AnimatePresence>
  );
};

const App = () => (
  <Router>
    <AppRouter />
  </Router>
);

export default App;
