import React, { useEffect, useState } from 'react';
import Head from './partials/head';
import Navbar from './partials/navbar';
import Footer from './partials/footer';
import config from '../config';
import axios from 'axios';

const CreateTable = () => {
  const [games, setGames] = useState([]);
  const [status, setGETSTATUS] = useState(true);
  const [isLoading, setIsLoading] = useState(true); // Trạng thái loading

  useEffect(() => {
    axios
      .post(`${config.API_URL}/viewTable`)
      .then((response) => {
        setGames(response.data.data || []);
        setGETSTATUS(response.data.type);
      })
      .catch((error) => {
        console.error('Error loading game data:', error.message);
      })
      .finally(() => {
        setIsLoading(false); // Dừng trạng thái loading sau khi hoàn tất
      });
  }, []);

  if (isLoading) {
    // Hiển thị spinner hoặc nội dung chờ trong khi tải dữ liệu
    return (
      <div className="d-flex justify-content-center align-items-center" style={{ height: '50vh' }}>
        <div className="spinner-border text-primary" role="status">
          <span className="sr-only">Loading...</span>
        </div>
      </div>
    );
  }

  if (!games || games.length === 0 || !status) {
    return (
      <article className="col-md-6 col-lg-4 col-6 p-0">
        <div className="alert alert-warning text-center" role="alert">
          <strong>WARNING !!!! Không có dữ liệu !!</strong>
        </div>
      </article>
    );
  }

  return (
    <div className="container-lg">
      {games.map(({ id, title, updatedAt, data }) => (
        <div key={id}>
          <h2 className="guide__title">{title}</h2>
          <div className="row item-container">
            {data.map(({ id, content, bgimage, quantity }) => (
              <div key={id} className="col-md-3 mb-4">
                <div className="item-bounder">
                  <div className="item-image mb-3">
                    <a href={`#/account/category/${id}`}>
                      <img src={bgimage || 'default-image-url.jpg'} alt="Game Category" className="img-fluid" />
                    </a>
                  </div>
                  <div className="item-caption">
                    <h3 className="text-center">{content}</h3>
                  </div>
                  <div className="text-center">
                    <img
                      width="90%"
                      className="img-responsive"
                      src="https://raw.githubusercontent.com/demoiiiiibtca/img/refs/heads/main/hr_beautiful.webp"
                      alt="Game Thumbnail"
                    />
                  </div>
                  <a
                    href={`#/account/category/${id}`}
                    className="btn btn"
                    role="button"
                    style={{ background: 'none', border: 'none' }}
                  >
                    <img
                      style={{ pointerEvents: 'none', background: 'none', maxWidth: '100%', height: 'auto' }}
                      src="https://raw.githubusercontent.com/demoiiiiibtca/img/refs/heads/main/btnview.gif"
                      alt="NICK NRO TRUNG - VIP"
                    />
                  </a>

                  <div className="account-remaining mt-3 text-center">
                    <p>
                      <strong>Còn {quantity} tài khoản</strong>
                    </p>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
};

const Home = () => {
  return (
    <>
      <Head />
      <div className="hold-transition sidebar-collapse layout-top-nav">
        <div className="wrapper">
          <Navbar />

          <section className="content">
            <div className="container-fluid">
              <center>
              {/* eslint-disable-next-line jsx-a11y/alt-text */}
                <img
                  src="https://raw.githubusercontent.com/demoiiiiibtca/img/refs/heads/main/2020031919242255224.png"
                  className="city__icon"
                />
              </center>

              <main>
                <div>
                  <div className="container-lg mb-3">
                    <div className="row mb-3">
                      <div className="col text-center">
                        <span className="mt-2">
                         {/* eslint-disable-next-line jsx-a11y/anchor-is-valid */}
                          <a
                            href="#"
                            className="dropdown-toggle"
                            data-toggle="dropdown"
                            aria-haspopup="true"
                            aria-expanded="false"
                          >
                            <button className="btn-pretty">Hỗ Trợ</button>
                          </a>
                          <div className="dropdown-menu">
                            <div className="dropdown-divider"></div>
                          </div>
                        </span>

                        <span className="mt-2">
                          {/* eslint-disable-next-line jsx-a11y/anchor-is-valid */}
                          <a
                            href="#"
                            className="dropdown-toggle"
                            data-toggle="dropdown"
                            aria-haspopup="true"
                            aria-expanded="false"
                          >
                            <button className="btn-pretty">Nạp Tiền</button>
                          </a>
                          <div className="dropdown-menu">
                            <a className="dropdown-item" href="/#">
                              <i className="fas fa-university mr-1"></i> Chuyển Khoản
                            </a>
                          </div>
                        </span>
                      </div>
                    </div>
                  </div>
                  <CreateTable />
                </div>
              </main>
              <Footer />
            </div>
          </section>
        </div>
      </div>
    </>
  );
};

export default Home;
