import React, { useState } from 'react';
import { useNavigate } from "react-router-dom";
import Head from './partials/head';
import Navbar from './partials/navbar';
import Footer from './partials/footer';
import { ToastContainer, toast } from "react-toastify"; // Importing react-toastify
import "react-toastify/dist/ReactToastify.css"; // Importing default styles
import config from '../config';
import axios from 'axios';

const Login = () => {
  const navigate = useNavigate();
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);  // To track the loading state

  const handleLogin = async () => {
    if (username === "" || password === "") {
      toast.error("Tài khoản và mật khẩu không được để trống!", {position: "top-right",autoClose: 5000,hideProgressBar: false,closeOnClick: true});
      return;
    }

    setLoading(true);

    try {
      const response = await axios.post(`${config.API_URL}/login`, {
        username: username,
        password: password,
      });
      if (response.data.type) {
        localStorage.setItem("authorization", response.data.data.AccessKey);
        toast.success("Đăng nhập thành công!", { position: "top-right", autoClose: 5000, hideProgressBar: false, closeOnClick: true });
        navigate("/");
      } else {
        toast.error("Đăng nhập thất bại! Tài khoản hoặc mật khẩu sai.", {position: "top-right",autoClose: 5000,hideProgressBar: false,closeOnClick: true});
      }
    } catch (error) {
      console.error("Error logging in:", error.message);
      toast.error("Error logging in.", {position: "top-right",autoClose: 5000,hideProgressBar: false,closeOnClick: true});
    }

    setLoading(false); // Stop loading
  };

  return (
    <>
      <Head />
      <div className="hold-transition sidebar-collapse layout-top-nav">
        <div className="wrapper">
          <Navbar />
          <h1 className="guide__title">Login</h1>
          <section className="content">
            <div className="container">
              <div className="row justify-content-center">
                <div className="col-md-8">
                  <div className="card" style={{ boxShadow: 'unset' }}>
                    <div className="card-body">
                      <div className="mb-3">
                      </div>

                      <div className="text-center mb-4">
                        <h1>Login App</h1>
                      </div>

                      <form>
                        <div className="form-group row">
                          <label htmlFor="username" className="col-md-4 col-form-label text-md-right">
                            Tài khoản
                          </label>
                          <div className="col-md-6">
                            <input
                              id="username"
                              type="text"
                              className="form-control"
                              name="username"
                              required
                              placeholder="Tài khoản từ 2 đến dưới 200 kí tự"
                              autoComplete="username"
                              autoFocus
                              onChange={(e) => setUsername(e.target.value)}
                            />
                          </div>
                        </div>

                        <div className="form-group row">
                          <label htmlFor="password" className="col-md-4 col-form-label text-md-right">
                            Mật khẩu
                          </label>
                          <div className="col-md-6">
                            <input
                              id="password"
                              type="password"
                              className="form-control"
                              name="password"
                              required
                              placeholder="Mật khẩu từ 2 đến dưới 200 kí tự"
                              autoComplete="current-password"
                              onChange={(e) => setPassword(e.target.value)}
                            />
                          </div>
                        </div>

                        <div className="form-group row">
                          <div className="col-md-6 offset-md-4">
                            <a href="#/forgot-password" className="btn btn-link">
                              Quên mật khẩu?
                            </a>
                          </div>
                        </div>

                        <div className="form-group row">
                          <div className="col-md-6 offset-md-4">
                            <button
                              type="button"
                              onClick={handleLogin}
                              className="btn btn-primary"
                              disabled={loading || username === "" || password === ""}
                            >
                              {loading ? 'Đang đăng nhập...' : 'Login App'}
                            </button>
                          </div>
                        </div>
                      </form>
                    </div>
                  </div>
                </div>
              </div>
              <Footer />
              <ToastContainer />
            </div>
          </section>
        </div>
      </div>
    </>
  );
};

export default Login;
