import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';
import config from '../config';
import Head from './partials/head';
import Navbar from './partials/navbar';
import Footer from './partials/footer';

import FormSearch from './account-category-formsearch/v1'; //2 version, v2 and v1

// Table Component
const Table = () => {
  const { id } = useParams();
  const [viewGameCategory, setViewGameCategory] = useState([]);
  const [searchParams, setSearchParams] = useState({ accId: '', server: '', sortPrice: '-1' });
  const [pagination, setPagination] = useState({ currentPage: 1, totalPages: 1, totalRecords: 0 });
  const [isLoading, setIsLoading] = useState(false);
  const [checkSTT, setCheckSTT] = useState(true);

  const formatPrice = (num) => num.toLocaleString('vi');

  const handleSearch = (params) => {
    setSearchParams(params);
    setPagination((prev) => ({ ...prev, currentPage: 1 })); // Reset to first page on new search
  };

  const handlePageChange = (page) => setPagination((prev) => ({ ...prev, currentPage: page }));

  useEffect(() => {
    const fetchData = async () => {
      setIsLoading(true);
      try {
        const response = await axios.post(`${config.API_URL}/viewGame_category`, {
          gameId: id,
          ...searchParams,
          page: pagination.currentPage,
        });
        if (response.data.type) {
          const { data, pagination: pag } = response.data;
          setViewGameCategory(data || []);
          setPagination({ ...pagination, totalPages: pag.totalPages, totalRecords: pag.totalRecords });
        }
        setCheckSTT(response.data.type);
      } catch (error) {
        console.error('Error:', error.message);
        setCheckSTT(false);
      } finally {
        setIsLoading(false);
      }
    };
    fetchData();
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [id, searchParams, pagination.currentPage]);

  const renderPagination = () => (
    <div className="pagination-container d-flex justify-content-center mt-4">
      <nav>
        <ul className="pagination">
          <li className={`page-item ${pagination.currentPage <= 1 ? 'disabled' : ''}`}>
            <button
              onClick={() => handlePageChange(pagination.currentPage - 1)}
              className="page-link"
              aria-label="Previous"
            >
              <span aria-hidden="true">&laquo;</span>
            </button>
          </li>
  
          {/* Hiển thị các số trang */}
          {Array.from({ length: pagination.totalPages }, (_, i) => i + 1).map((page) => (
            <li
              key={page}
              className={`page-item ${pagination.currentPage === page ? 'active' : ''}`}
            >
              <button
                onClick={() => handlePageChange(page)}
                className="page-link"
              >
                {page}
              </button>
            </li>
          ))}
  
          <li className={`page-item ${pagination.currentPage >= pagination.totalPages ? 'disabled' : ''}`}>
            <button
              onClick={() => handlePageChange(pagination.currentPage + 1)}
              className="page-link"
              aria-label="Next"
            >
              <span aria-hidden="true">&raquo;</span>
            </button>
          </li>
        </ul>
      </nav>
    </div>
  );
  

  return (
    <>
      <FormSearch onSearch={handleSearch} isLoading={isLoading} />
      {isLoading ? (
        <div className="text-center mt-4">
          <div className="spinner-border text-primary" role="status">
            <span className="sr-only">Loading...</span>
          </div>
        </div>
      ) : (
        <>
          {viewGameCategory.length > 0 && checkSTT ? (
            <>
              <div className="row">
                {viewGameCategory.map((item) => (
                  <article className="col-md-6 col-lg-4 col-6 p-0" key={item._id}>
                    <div className="genshin-product">
                      <div className="wrapper product-wrapper">
                        <a href={`#/account/info/${item._id}`}>
                          <div className="image-container">
                            <span className="ms position-absolute top-0 start-0 bg-danger text-white p-1" style={{ zIndex: 10, borderRadius: '5px' }}>
                              ID: <b>{item.idnew}</b>
                            </span>
                            {/* eslint-disable-next-line jsx-a11y/img-redundant-alt */}
                            <img
                              style={{ borderRadius: '0.3rem' }}
                              src={item.bgimage?.[0] || 'default-image-url.jpg'}
                              className="xc"
                              alt="Product Image"
                            />
                          </div>
                        </a>
                        <div className="price_cate">
                          <div className="row">
                            <div>
                              <span className="text_price_cate text-success">
                                <i className="fas fa-dollar-sign"></i> {formatPrice(item.price)}
                              </span>
                            </div>
                          </div>
                        </div>
                        <a href={`#/account/info/${item._id}`} style={{ color: 'unset' }}>
                          <div className="row g-0 info-line">
                            <section className="col text-center">
                              <label>Hành Tinh</label> {item.planet}
                            </section>
                            <section className="col text-center">
                              <label>Máy Chủ</label> {item.server}
                            </section>
                          </div>
                          <div className="hr-product"></div>
                          <div className="row g-0 info-line">
                            <section className="row g-0 text-center">
                              <span className="more-detail">{item.content}</span>
                            </section>
                          </div>
                        </a>
                      </div>
                    </div>
                  </article>
                ))}
              </div>
              {renderPagination()}
            </>
          ) : (
            <div className="alert alert-warning text-center" role="alert">
              <strong>WARNING !!!! Không có dữ liệu !!</strong>
            </div>
          )}
        </>
      )}
    </>
  );
};


// AccountCategory Component
const AccountCategory = () => {
  return (
    <>
      <Head />
      <div className="hold-transition sidebar-collapse layout-top-nav">
        <div className="wrapper">
          <Navbar />
          <section className="content">
            <div className="container-fluid">
              {/* eslint-disable-next-line jsx-a11y/alt-text */}
              <center><img src="https://raw.githubusercontent.com/demoiiiiibtca/img/refs/heads/main/2020031919242255224.png" className="city__icon" /></center>
              <main>
                <div>
                  <div className="container-lg">
                    <div className="row">
                      <Table />
                    </div>
                  </div>
                </div>
              </main>
              <Footer />
            </div>
          </section>
        </div>
      </div>
    </>
  );
};

export default AccountCategory;
